from abc import ABCMeta, abstractmethod
import six
from taf.internal.managedobject import ManagedObject


@six.add_metaclass(ABCMeta)
class FilePutter(ManagedObject):
    """
    Object, which allows to put files from local host to remote host.
    """

    @abstractmethod
    def put_file(self, source_path, target_path):
        """
        Put a file at a source path on the local host to a target path on the remote host.

        :param str source_path: source path on local host
        :param str target_path: target path on remote host
        """
